                while k < 20.0 {
                    defer { k += 1 }
                    g.on(RX + k, RY + 2.0, ((JSMath.rem(k, 5.0) == 0.0 || k == 19.0) ? 0.5 : 0.2))
                    if (JSMath.rem(k, 5.0) == 0.0 || k == 19.0) {
                        g.on(RX + k, RY + 3.0, 0.5)
                    }
                    g.on(RX + k, RY, 0.12)
                }
            }
            do {
                var k: Double = 0.0
                while k < 20.0 {
                    defer { k += 1 }
                    for v in ([0.0, 1.0] as [Double]) {
                        let n: Double = k * 2.0 + v
                        let b: Double = ((hit || k < m) ? 0.86 + ((k == m - 1.0 ? 0.14 * mf : 0.0)) : (k == m ? ((v != 0 ? 0.2 + 0.6 * f : 0.12 + 0.5 * f)) : 0.0))
                        var x: Double = RX + k + 0.5
                        var y: Double = RY - v + 0.5
                        if hit {
                            let u: Double = eio((h - 0.04 - (19.0 - k) * 0.012) / 0.45)
                            let sq: Double = JSMath.rem(n, 9.0)
                            x = lerp(x, 33.0 + (JSMath.rem(sq, 3.0)) + 0.5, u)
                            y = lerp(y, 5.0 + JS.floor(sq / 3.0) + 0.5, u)
                        }
                        g.fr(x, y, b)
                    }
                }
            }
            let px: Double = RX + JS.min(20.0, m + f)
            do {
                var v: Double = 0.0
                while v < 4.0 {
                    defer { v += 1 }
                    g.fr(px, RY - 2.5 + v, (hit ? 0.0 : (v != 0 ? 0.55 : 1.0)), (v != 0 ? 0 : 1))
                }
            }
            return SceneOut(opts: MatrixDealOptions(stagger: 0.4), flash: (hit ? fl(h, 0.1, 0.12) + fl(h - land, 0.18, 0.3) : mf * 0.05), shake: (((hit && h > land) && h < land + 0.14) ? 0.22 : 0.0))
        }
        public static let SCENES: [MatrixScene] = [sunDial, tiles, monitor, wedge, arrow, stopwatch, weekZoom]
    }
}
